package com.google.gson.internal.bind;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import com.google.gson.JsonToken;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import java.io.*;
import java.io.IOException;
import java.io.Reader;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import java.util.Iterator;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

@RunWith(org.mockito.junit.MockitoJUnitRunner.class)
public class JsonTreeReader_skipValue_TriageGen0Test {

    private JsonTreeReader jsonTreeReader;

    @Mock
    private JsonReader mockJsonReader;

    @Before
    public void setUp() throws IOException {
        MockitoAnnotations.initMocks(this);
        jsonTreeReader = new JsonTreeReader(new JsonElement(new JsonObject()));
        when(jsonTreeReader.peek()).thenReturn(JsonToken.NAME, JsonToken.NULL, JsonToken.END_OBJECT);
        when(jsonTreeReader.nextName()).thenReturn("testName");
    }

    @Test
    public void testSkipValueWithNameToken() throws IOException {
        jsonTreeReader.skipValue();
        verify(jsonTreeReader).nextName();
        assertEquals("null", jsonTreeReader.getPathNames()[jsonTreeReader.getStackSize() - 2]);
    }

    @Test
    public void testSkipValueWithNonNameToken() throws IOException {
        jsonTreeReader.peek(); // Simulate NAME token
        jsonTreeReader.skipValue();
        jsonTreeReader.peek(); // Simulate non-NAME token
        jsonTreeReader.skipValue();
        assertEquals("null", jsonTreeReader.getPathNames()[jsonTreeReader.getStackSize() - 1]);
    }

    @Test(expected = IOException.class)
    public void testSkipValueWithNullTokenThrowsIOException() throws IOException {
        jsonTreeReader.peek(); // Simulate NAME token
        jsonTreeReader.skipValue();
        jsonTreeReader.peek(); // Simulate NULL token
        jsonTreeReader.skipValue();
        jsonTreeReader.peek(); // Simulate END_OBJECT token
        jsonTreeReader.skipValue();
    }

    @Test(expected = IllegalStateException.class)
    public void testSkipValueWithEmptyStack() throws IOException {
        jsonTreeReader = new JsonTreeReader(new JsonElement(JsonNull.INSTANCE));
        jsonTreeReader.skipValue();
    }

    @Test
    public void testSkipValueWithMultipleCalls() throws IOException {
        jsonTreeReader.skipValue();
        jsonTreeReader.peek(); // Simulate non-NAME token
        jsonTreeReader.skipValue();
        jsonTreeReader.peek(); // Simulate non-NAME token
        jsonTreeReader.skipValue();
        assertEquals(2, jsonTreeReader.getPathIndices()[jsonTreeReader.getStackSize() - 1]);
    }

    @Test
    public void testSkipValueWithNullValue() throws IOException {
        jsonTreeReader = new JsonTreeReader(new JsonElement(JsonNull.INSTANCE));
        jsonTreeReader.skipValue();
        assertEquals("null", jsonTreeReader.getPathNames()[jsonTreeReader.getStackSize() - 1]);
    }
}
